      </section>

      <section class="faq-shell" aria-label="Cat frequently asked questions">
        <div id="faq-root" class="faq-list"></div>
      </section>
    </main>

    <script>
      const faqs = [
        {
          question: "How often should I feed my cat?",
          answer:
            "Most adult cats do well with two measured meals per day, though kittens and cats with medical needs may require a different schedule. Follow your veterinarian's guidance and the feeding instructions for your cat's food."
        },
        {
          question: "Why does my cat knead blankets or my lap?",
          answer:
            "Kneading is a normal comfort behavior that begins in kittenhood. Adult cats often knead when they feel relaxed, secure, or ready to settle in for a nap."
        },
        {
          question: "Do indoor cats need enrichment?",
          answer:
            "Yes. Indoor cats need daily play, scratching surfaces, hiding spots, window views, and vertical spaces. Enrichment helps prevent boredom and supports healthy movement."
        },
        {
          question: "How much water should my cat drink?",
          answer:
            "Water needs vary by diet, age, activity level, and health. Provide fresh water every day, consider a fountain if your cat prefers moving water, and contact a veterinarian if drinking suddenly increases or decreases."
        },
        {
          question: "When should my cat visit the veterinarian?",
          answer:
            "Healthy adult cats should usually have a wellness exam once a year. Senior cats, kittens, and cats with chronic conditions may need more frequent visits."
        }
      ];

      function FAQItem({ question, answer }, index) {
        const buttonId = `faq-button-${index}`;
        const detailsId = `faq-details-${index}`;

        return `
          <div class="example">
            <h2>
              <button
                id="${buttonId}"
                class="question-button"
                type="button"
                aria-expanded="false"
                aria-controls="${detailsId}"
              >
                <span>${question}</span>
                <span class="icon" aria-hidden="true">+</span>
              </button>
            </h2>
            <div id="${detailsId}" class="details" role="region" aria-labelledby="${buttonId}" hidden>
              <p>${answer}</p>
            </div>
          </div>
        `;
      }

      function FAQPage(items) {
        return items.map(FAQItem).join("");
      }

      const root = document.querySelector("#faq-root");
      root.innerHTML = FAQPage(faqs);

      root.addEventListener("click", (event) => {
        const button = event.target.closest(".question-button");
        if (!button) {
          return;
        }

        const details = document.getElementById(button.getAttribute("aria-controls"));
        const expanded = button.getAttribute("aria-expanded") === "true";

        button.setAttribute("aria-expanded", String(!expanded));
        details.hidden = expanded;
      });
    </script>
